            argsC.emplace_back(strdup(arg.c_str()));
        }

        argsC.emplace_back(nullptr);

        // pass env
        for (auto& [n, v] : m_impl->env) {
            setenv(n.c_str(), v.c_str(), 1);
        }

        execvp(m_impl->binary.c_str(), argsC.data());
        for (auto ptr : argsC) {
            if (ptr)
                free(ptr);
        }
        _exit(1);

    } else {
        // parent
        close(outPipe[1]);
        close(errPipe[1]);

        m_impl->out = "";
        m_impl->err = "";

        m_impl->grandchildPid = pid;

        std::array<char, 1024> buf;
        buf.fill(0);

