        close(outPipe[0]);
        close(errPipe[0]);

        // reap child
        int status = 0;
        waitpid(pid, &status, 0);

        if (WIFEXITED(status))
            m_impl->exitCode = WEXITSTATUS(status);

        return true;
    }

    return true;
}

